<?php
require_once '../config/session.php'; require_once '../config/config.php';
if(empty($_SESSION['user_id'])||($_SESSION['user_role']??'')!=='student'){header('Location: ../auth/login.php');exit;}
$rows=$conn->query("SELECT r.exam_id,e.title,s.full_name,MAX(r.percentage) percentage,MAX(r.obtained_marks) obtained_marks FROM results r JOIN exams e ON e.id=r.exam_id JOIN students s ON s.id=r.student_id GROUP BY r.exam_id,r.student_id ORDER BY r.exam_id,percentage DESC,obtained_marks DESC")->fetchAll(PDO::FETCH_ASSOC);$rank=0;$last_exam=null;$last_percent=null;$shown_rank=0;
?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Leaderboard | ExamSphere</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.7/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><link rel="stylesheet" href="assets/css/dashboard.css"><link rel="stylesheet" href="../assets/css/main.css"></head><body><?php include 'includes/navbar.php';?><main class="container py-5"><h1>Leaderboard</h1><p class="text-muted">Best score per student for each exam. Only names and performance are shown.</p><div class="card border-0 shadow-sm p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Exam</th><th>Rank</th><th>Student</th><th>Score</th><th>Percentage</th></tr></thead><tbody><?php foreach($rows as $row):if($last_exam!==$row['exam_id']){$rank=0;$shown_rank=0;$last_percent=null;$last_exam=$row['exam_id'];}$rank++;if($last_percent===null||$last_percent!=$row['percentage'])$shown_rank=$rank;$last_percent=$row['percentage'];?><tr><td><?=htmlspecialchars($row['title'])?></td><td>#<?=$shown_rank?></td><td><?=htmlspecialchars($row['full_name'])?></td><td><?=$row['obtained_marks']?></td><td><?=$row['percentage']?>%</td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="text-center text-muted py-4">No result data is available for the leaderboard yet.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>
